#include "stdafx.h"#define __MAIN_FILE__#include "KeybCOM.h"#include "Resource.h"#include <ShellApi.h>#include <stdio.h>//#include "YokoUSB.h"CYokoUSB usb;#define MAX_LOADSTRING 100extern int DEFAULT_VENDOR_ID  ;//        0x0DF9extern int DEFAULT_PRODUCT_ID ;//        0x0001extern int DEFAULT_TRANSFERRED;//        0x0007extern HWND g_hSendWnd;// Global Variables:TCHAR szTitle[MAX_LOADSTRING];// The title bar text// Forward declarations of functions included in this code module:ATOM MyRegisterClass(HINSTANCE hInstance, LPCTSTR pszClass);LRESULT CALLBACK	WndProc(HWND, UINT, WPARAM, LPARAM);LRESULT CALLBACK	About(HWND, UINT, WPARAM, LPARAM);NOTIFYICONDATA NI;//char szServer[256] = "";void StartService(void);void StopService(void);//UINT nIconMessage = ::RegisterWindowMessageA("¨лочка гори!!");////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void ParserCmdLine(char* ptr)	{	// Определяем ключи программы	while ( *ptr )		{		while ( *ptr == ' ' ) ptr++;//Пропуск пробелов		char* str = ptr; //Поиск конца ключа		if ( *ptr == '"' ) //Если в имени есть пробел			{			ptr++;str++;			while ( *str && *str != '"' ) str++;//Идем до конца ключа			}		else			{			while ( *str && *str != ' ' ) str++;//Пропуск НЕпробелов			}		char ch = *str;		*str = '\0';		if ( *ptr == '/' || *ptr == '-' )			{			char key = toupper(ptr[1]);			ptr += 2;//Skip '/' & key							if ( *ptr == '"' ) //Если в имени есть пробел				{				ptr++;*str = ch;str = ptr;				while ( *str && *str != '"' ) str++;//Идем до конца ключа				ch = *str;				*str = '\0';				}      //			switch ( key )				{        case 'S':          lstrcpy ( szServer, ptr );          break;        case 'V':          sscanf_s( ptr, "%x", &DEFAULT_VENDOR_ID );          break;        case 'P':          sscanf_s( ptr, "%x", &DEFAULT_PRODUCT_ID );          break;        case 'T':          sscanf_s( ptr, "%x", &DEFAULT_TRANSFERRED );          break;        };      //			}			*str = ch;			ptr = str;			if ( !*ptr ) ptr--;// Чтобы не вылезти за пределы массива			ptr++;		}  }//int APIENTRY _tWinMain(HINSTANCE hInstance, HINSTANCE , LPTSTR pszCmdLine, int nCmdShow)  {  ParserCmdLine(pszCmdLine);  //  HWND hWnd;  if ( ::IsKeySensor( hWnd ) )    {    //MessageBox(NULL,szWinName,NULL,0);    return 0; //Запрет на несколько экземпляров    }  //  if ( !usb.OpenUSB() )    {    usb.CloseUSB();    return 0;    }  // Initialize global strings	LoadString(hInstance, IDS_APP_TITLE, szTitle, MAX_LOADSTRING);  //	MyRegisterClass(hInstance, szClassNameSensor);  //	// Perform application initialization:	if (!usb.Create(hInstance))     return FALSE;	HACCEL hAccelTable = LoadAccelerators(hInstance, (LPCTSTR)IDC_KEYBCOM);	MSG msg;  memset( &msg, 0, sizeof(msg) );	// Main message loop:  StartService();	while (GetMessage(&msg, NULL, 0, 0)) 	  {		if (!TranslateAccelerator(msg.hwnd, hAccelTable, &msg)) 		  {			TranslateMessage(&msg);			DispatchMessage(&msg);		  }	  }  StopService();  usb.CloseUSB();  return (int) msg.wParam;  }//ATOM MyRegisterClass(HINSTANCE hInstance, LPCTSTR pszClass)  {  WNDCLASSEX wcex;  wcex.cbSize = sizeof(WNDCLASSEX);   wcex.style			= CS_HREDRAW | CS_VREDRAW;  wcex.lpfnWndProc	= (WNDPROC)WndProc;  wcex.cbClsExtra		= 0;  wcex.cbWndExtra		= 0;  wcex.hInstance		= hInstance;  wcex.hIcon			= LoadIcon(hInstance, (LPCTSTR)IDI_SMALL);  wcex.hCursor		= LoadCursor(NULL, IDC_ARROW);  wcex.hbrBackground	= (HBRUSH)::GetStockObject(BLACK_BRUSH);  wcex.lpszMenuName	= NULL;  wcex.lpszClassName	= pszClass;  wcex.hIconSm		= LoadIcon(wcex.hInstance, (LPCTSTR)IDI_SMALL);  NI.hIcon = wcex.hIconSm;  return RegisterClassEx(&wcex);  }//LRESULT CALLBACK WndProc(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam)  {  //  if ( uMsg == nIconMessage && lParam == WM_RBUTTONUP )    {    HMENU hMenu = ::CreatePopupMenu();    if ( hMenu )      {      UINT u = MF_BYCOMMAND | MF_ENABLED;      if ( ::IsWindowVisible(hWnd) )        ::AppendMenu(hMenu,u,101,"Спрятать окно");      else        ::AppendMenu(hMenu,u,100,"Показать окно");      ::AppendMenu(hMenu,MF_SEPARATOR,0,0);      ::AppendMenu(hMenu,u,102,"Завершить работу...");      ::AppendMenu(hMenu,u,103,"Выход из меню");      //      POINT point;      ::GetCursorPos( &point );	    ::SetForegroundWindow(hWnd); //?      ::TrackPopupMenu(hMenu,TPM_LEFTALIGN|TPM_LEFTBUTTON|TPM_RIGHTBUTTON,                   point.x,point.y,0,hWnd,NULL);      ::DestroyMenu(hMenu);      }    }  if ( uMsg == nIconMessage && lParam == WM_LBUTTONDBLCLK )    {    ::ShowWindow( hWnd, SW_SHOWNORMAL );    ::SetForegroundWindow( hWnd );    }  //  if ( uMsg == nSensorsKeyboard && wParam == SET_WND )    {    g_hSendWnd = (HWND)lParam;    }  //	switch (uMsg) 	  {    case WM_CREATE:      {      NI.cbSize = sizeof ( NI );       NI.hWnd = hWnd;       NI.uID = 1001;       NI.uFlags = NIF_ICON|NIF_MESSAGE|NIF_TIP;       NI.uCallbackMessage = nIconMessage;       lstrcpy ( NI.szTip,szTitle); 	    Shell_NotifyIcon( NIM_ADD, &NI );       }    break;    case WM_DESTROY:      {      if ( !usb.Close() )        return 0;  	  Shell_NotifyIcon( NIM_DELETE, &NI );       ::PostQuitMessage( 0 );      }    break;    case WM_SIZE:      {      if ( wParam == SIZE_MINIMIZED )        {        ::ShowWindow( hWnd, SW_HIDE );        }      }    break;    //    case WM_SYSCOMMAND:      switch ( LOWORD( wParam ) )        {        case SC_CLOSE:          if ( !usb.Close() )            return 0;        break;        }    break;    //    case WM_COMMAND:      switch ( LOWORD( wParam ) )        {        case 100:// Показать окно          ::ShowWindow( hWnd, SW_SHOWNORMAL );          ::SetForegroundWindow( hWnd );          break;        case 101:// Спрятать окно          ::ShowWindow( hWnd, SW_HIDE );          break;        case 102:// Завершить работу          ::PostMessage( hWnd, WM_DESTROY, 0, 0 );          break;        case 103:// Выход          break;        case IDM_ABOUT:          DialogBox( ::GetModuleHandle(NULL), (LPCTSTR)IDD_ABOUTBOX, hWnd, (DLGPROC)About);        break;        case IDM_EXIT:          DestroyWindow(hWnd);        break;        }		break;    case WM_ERASEBKGND:      {      if ( !usb.Paint( (HDC)wParam ) )        ::DefWindowProc( hWnd, uMsg, wParam, lParam );      return 0;      }    break;    };  return DefWindowProc(hWnd, uMsg, wParam, lParam);  }//